import{_ as s,o as e,c as i,a2 as t}from"./chunks/framework.mRCPFc5l.js";const k=JSON.parse('{"title":"React Native iOS 环境排查","description":"按依赖层次定位 iOS 模拟器和 CocoaPods 问题，避免重复执行没有依据的修复命令。","frontmatter":{"title":"React Native iOS 环境排查","description":"按依赖层次定位 iOS 模拟器和 CocoaPods 问题，避免重复执行没有依据的修复命令。"},"headers":[],"relativePath":"web/frontend/reactNative.md","filePath":"web/frontend/reactNative.md","lastUpdated":1786262003000}'),d={name:"web/frontend/reactNative.md"};function o(n,a,l,p,c,r){return e(),i("div",null,[...a[0]||(a[0]=[t(`<h1 id="react-native-ios-环境排查" tabindex="-1">React Native iOS 环境排查 <a class="header-anchor" href="#react-native-ios-环境排查" aria-label="Permalink to &quot;React Native iOS 环境排查&quot;">​</a></h1><p>React Native 的 iOS 启动链路跨越 Node、Ruby、CocoaPods、Xcode 和 Simulator。遇到“无法打开模拟器”时，不要先清缓存；先确认错误发生在哪一层。</p><h2 id="先收集最小事实" tabindex="-1">先收集最小事实 <a class="header-anchor" href="#先收集最小事实" aria-label="Permalink to &quot;先收集最小事实&quot;">​</a></h2><p>在项目根目录执行命令前，确认项目 README 规定的 Node、包管理器、Xcode 和 Ruby/CocoaPods 版本。随后记录第一条真正报错，而不是只看命令最后一行。</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">xcodebuild</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -version</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><p>这些命令只用于确认本机环境。版本不符合项目约定时，先切换到要求的版本，再重新安装依赖。</p><h2 id="按顺序检查启动链路" tabindex="-1">按顺序检查启动链路 <a class="header-anchor" href="#按顺序检查启动链路" aria-label="Permalink to &quot;按顺序检查启动链路&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层次</th><th>常见症状</th><th>优先动作</th></tr></thead><tbody><tr><td>JavaScript 依赖</td><td>找不到 CLI、模块缺失</td><td>在项目根目录按锁文件安装依赖</td></tr><tr><td>Pods</td><td><code>pod install</code> 失败、iOS 原生库缺失</td><td>进入 <code>ios</code> 目录查看 Pod 错误</td></tr><tr><td>Xcode 工程</td><td>编译签名、SDK、架构错误</td><td>使用 <code>.xcworkspace</code> 打开工程查看完整日志</td></tr><tr><td>Simulator</td><td>没有可用设备、无法启动</td><td>在 Xcode 中确认运行时和设备已安装</td></tr></tbody></table><h2 id="pods-变更后的常用流程" tabindex="-1">Pods 变更后的常用流程 <a class="header-anchor" href="#pods-变更后的常用流程" aria-label="Permalink to &quot;Pods 变更后的常用流程&quot;">​</a></h2><p>当 JavaScript 原生依赖发生变化，或 <code>Podfile.lock</code> 与依赖状态不一致时，在项目约定的包管理器完成安装后执行：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ios</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ..</span></span></code></pre></div><p>只有在确认 Pods 状态已经损坏、且团队允许重新生成依赖时，才考虑 <code>pod deintegrate</code> 后再安装。它会修改 iOS 集成状态，不应作为遇错就执行的通用命令。</p><h2 id="为什么优先打开-xcworkspace" tabindex="-1">为什么优先打开 <code>.xcworkspace</code> <a class="header-anchor" href="#为什么优先打开-xcworkspace" aria-label="Permalink to &quot;为什么优先打开 \`.xcworkspace\`&quot;">​</a></h2><p>CocoaPods 集成后，应用工程与 Pods 工程需要由 workspace 一起加载。直接打开 <code>.xcodeproj</code> 可能看起来“少了依赖”，从而得到误导性的编译错误。</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">open</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ios/YourApp.xcworkspace</span></span></code></pre></div><p>将 <code>YourApp</code> 替换为实际工程名称。之后在 Xcode 的 Report navigator 中查看完整构建日志，通常比终端最后几十行更容易定位第一处失败。</p><h2 id="避免无效的环境操作" tabindex="-1">避免无效的环境操作 <a class="header-anchor" href="#避免无效的环境操作" aria-label="Permalink to &quot;避免无效的环境操作&quot;">​</a></h2><ul><li>不要把全局安装 CocoaPods 当成所有问题的解法；优先遵循项目的 Bundler 或版本管理约定。</li><li>不要删除 <code>node_modules</code>、Pods 或 DerivedData 作为第一步；先确认缓存与错误有关。</li><li>不要在未确认团队支持的 Xcode / iOS 版本上升级锁文件。</li><li>把“命令、首条错误、环境版本、已验证的操作”一并记录，下一次排查会快得多。</li></ul>`,18)])])}const u=s(d,[["render",o]]);export{k as __pageData,u as default};
